为了正确实现快速排序，下面横线上的代码应为()。
void qsort(vector<int>& arr, int left, int right){
    int i, j, mid;
    int pivot;
    i = left;
    j = right;
    mid = (left + right) / 2;
    pivot = arr[mid];
    do {
        while (arr[i] < pivot) i++;
        while (arr[j] > pivot) j--;
        if (i <= j){
            swap(arr[i], arr[j]);
            i++; j--;
        }
    } //在此处填入代码
    if (left < j) qsort(arr, left, j);
    if (i < right) qsort(arr, i, right);
}

根据下述二分查找法，在排好序的数组1,3,6,9,17,31,39,52,61,79,81,90,96中查找数值82，和82比较的数组元素分别是()。
int binary_search(vector<int>& nums, int target) {
    int left = 0;
    int right = nums.size() - 1;
    while (left <= right){
        int mid = (left + right) / 2;
        if (nums[mid] == target){
            return mid;
        } else if (nums[mid] < target){
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

